/**
 * Структура боковой панели «Справочник».
 *
 * Панель описана ЯВНО (не autogenerated): разделы «Направления работы» и
 * «Тематические программы» собраны в сворачиваемые смысловые группы, порядок
 * страниц задаётся порядком в этом файле. Frontmatter sidebar_position в
 * markdown-файлах при явной панели не используется (порядок — только здесь).
 *
 * Как добавить страницу:
 * 1. Создайте файл docs/<раздел>/<имя>.md — её адрес будет /docs/<раздел>/<имя>.
 * 2. Впишите id '<раздел>/<имя>' в нужный список ниже. Страница, не внесённая
 *    в панель, на сайте не появится.
 *
 * URL сохранены прежними: группы-подразделы — только метки навигации без
 * собственных страниц, а ссылки разделов ведут на прежние индексные адреса
 * (slug в section() совпадает с именем папки).
 */

/** Раздел верхнего уровня со сводной страницей-индексом. */
function section(label, slug, description, items) {
  return {
    type: 'category',
    label,
    link: { type: 'generated-index', slug, description },
    items,
  };
}

/** Сворачиваемая подгруппа внутри раздела (собственной страницы не имеет). */
function group(label, items) {
  return {
    type: 'category',
    label,
    collapsible: true,
    collapsed: true,
    items,
  };
}

